  "high_order_assessment": [
    {
      "active_model_action": true,
      "citations": [
        {
          "event_id": "lite_evt_00065",
          "explanation": "The doctor creates a tiered compromise: local assessment today, but only with adequate medical capability and transfer criteria.",
          "quote": "若护士站只能换药而无医生评估，请改去当地医院外科/急诊"
        },
        {
          "event_id": "lite_evt_00728",
          "explanation": "The plan later incorporates transport/offloading execution support.",
          "quote": "路上继续轮椅转运、患足完全不落地"
        }
      ],
      "completion": "complete",
      "explanation": "HO1 was triggered by the family's question about nearby care and travel/cost burden. The doctor separated local dressing/observation from specialist/emergency needs, preserved red-flag escalation, added offloading and documents/medication supports, and obtained repeated caregiver confirmations that the plan was executable.",
